<?php require_once 'bootstrap.php';$u=require_admin();$sic=$_GET['event']??$_POST['event']??'';$st=db()->prepare('SELECT * FROM events WHERE sic_id=?');$st->execute([$sic]);$e=$st->fetch();if(!$e){http_response_code(404);exit('Evento non trovato');}if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$reg=$_POST['registration']??'';$r=db()->prepare('SELECT * FROM event_registrations WHERE sic_id=? AND event_sic_id=?');$r->execute([$reg,$sic]);$row=$r->fetch();if($row&&$row['status']!=='CHECKED_IN'){db()->prepare("UPDATE event_registrations SET status='CHECKED_IN',checked_in_at=CURRENT_TIMESTAMP,verified_by_sic_id=? WHERE sic_id=?")->execute([$u['sic_id'],$reg]);$reward=(float)$e['drx_reward'];if($reward>0)drx_post($row['user_sic_id'],null,$reward,'EVENT_ATTENDANCE',true,'event-checkin:'.$sic.':'.$row['user_sic_id'],$sic,['event'=>$e['title']]);audit($u['sic_id'],'EVENT_CHECKIN',$reg,['event'=>$sic]);}}$regs=db()->prepare('SELECT er.*,u.display_name,u.email FROM event_registrations er JOIN users u ON u.sic_id=er.user_sic_id WHERE er.event_sic_id=? ORDER BY er.created_at');$regs->execute([$sic]);$rows=$regs->fetchAll();$pageTitle='Presenze evento';require '_header.php';?>
<section class="section-head"><div><span class="eyebrow">Verified Check-in</span><h1><?=h($e['title'])?></h1><p>Il DRX viene assegnato una sola volta dopo verifica presenza.</p></div></section><div class="course-list"><?php foreach($rows as $r):?><article class="course"><span class="course-cat"><?=h($r['status'])?></span><h3><?=h($r['display_name'])?></h3><p><?=h($r['email'])?></p><?php if($r['status']!=='CHECKED_IN'):?><form method="post"><input type="hidden" name="<?=CSRF_KEY?>" value="<?=h(csrf_token())?>"><input type="hidden" name="event" value="<?=h($sic)?>"><input type="hidden" name="registration" value="<?=h($r['sic_id'])?>"><button class="btn primary small">Conferma presenza</button></form><?php endif;?></article><?php endforeach;?></div><?php require '_footer.php';?>